import sys


# 处理一组测试数据，返回最少操作次数和操作下标列表
def solve_one(n, s):
    stack = []          # 存未匹配的 '(' 的下标
    bad_right = []      # 存未匹配的 ')' 的下标

    for i, ch in enumerate(s, 1):  # 下标从 1 开始
        if ch == '(':
            stack.append(i)
        else:
            if stack:
                stack.pop()        # 匹配掉一对括号
            else:
                bad_right.append(i)

    bad_left = stack               # 剩下的全是未匹配的 '('

    a = len(bad_right)
    b = len(bad_left)

    ans = []

    # 翻转最前面的 ceil(a / 2) 个未匹配 ')'
    need_right = (a + 1) // 2
    for i in range(need_right):
        ans.append(bad_right[i])

    # 翻转最后面的 ceil(b / 2) 个未匹配 '('
    need_left = (b + 1) // 2
    for i in range(b - need_left, b):
        ans.append(bad_left[i])

    return len(ans), ans


def main():
    input = sys.stdin.readline
    t = int(input().strip())
    out = []

    for _ in range(t):
        n = int(input().strip())
        s = input().strip()

        k, ans = solve_one(n, s)
        out.append(str(k))
        if k == 0:
            out.append("")
        else:
            out.append(" ".join(map(str, ans)))

    sys.stdout.write("\n".join(out))


if __name__ == "__main__":
    main()
```

### Java

```java
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.ArrayList;
import java.util.StringTokenizer;

public class Main {

    // 返回一组测试的答案
    static ArrayList<Integer> solveOne(int n, String s) {
        ArrayList<Integer> stack = new ArrayList<>();      // 存未匹配的 '(' 下标
        ArrayList<Integer> badRight = new ArrayList<>();   // 存未匹配的 ')' 下标

        for (int i = 0; i < n; i++) {
            char ch = s.charAt(i);
            int idx = i + 1; // 题目要求下标从 1 开始

            if (ch == '(') {
                stack.add(idx);
            } else {
                if (!stack.isEmpty()) {
                    // 匹配掉一对括号
                    stack.remove(stack.size() - 1);
                } else {
                    badRight.add(idx);
                }
            }
        }

        ArrayList<Integer> ans = new ArrayList<>();

        int a = badRight.size();
        int b = stack.size();

        // 翻转最前面的 ceil(a / 2) 个未匹配 ')'
        int needRight = (a + 1) / 2;
        for (int i = 0; i < needRight; i++) {
            ans.add(badRight.get(i));
        }

        // 翻转最后面的 ceil(b / 2) 个未匹配 '('
        int needLeft = (b + 1) / 2;
        for (int i = b - needLeft; i < b; i++) {
            ans.add(stack.get(i));
        }

        return ans;
    }

    public static void main(String[] args) throws Exception {
        FastReader fr = new FastReader();
        StringBuilder sb = new StringBuilder();

        int T = fr.nextInt();
        while (T-- > 0) {
            int n = fr.nextInt();
            String s = fr.next();

            ArrayList<Integer> ans = solveOne(n, s);

            sb.append(ans.size()).append('\n');
            if (ans.size() == 0) {
                sb.append('\n');
            } else {
                for (int i = 0; i < ans.size(); i++) {
                    if (i > 0) sb.append(' ');
                    sb.append(ans.get(i));
                }
                sb.append('\n');
            }
        }

        System.out.print(sb.toString());
    }

    // 简单输入工具
    static class FastReader {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;

        String next() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}
